<template>
  <section class="operation-block" aria-labelledby="customer-operations-title">
    <header><div><p class="module-eyebrow">KHÁCH HÀNG</p><h3 id="customer-operations-title">Khách mới & quay lại</h3><p>Phân nhóm theo hóa đơn paid trong lịch sử; khách đăng ký chưa mua không tính là khách mới.</p></div><button type="button" aria-label="Làm mới báo cáo khách hàng" title="Làm mới" :disabled="loading" @click="load">↻</button></header>
    <div v-if="error" class="block-error" role="alert">{{ error }} <button type="button" aria-label="Thử tải lại báo cáo khách hàng" @click="load">Thử lại</button></div><div v-else-if="loading" class="block-loading" role="status">Đang tải…</div>
    <template v-else-if="data"><div class="mini-kpis"><span><b>{{ data.summary.newBuyerCount }}</b> khách mới mua</span><span><b>{{ data.summary.returningBuyerCount }}</b> khách quay lại</span><span><b>{{ data.summary.anonymousInvoiceCount }}</b> bill vãng lai</span></div><div v-if="!data.rows.length" class="block-loading">Chưa có khách gắn với hóa đơn trong kỳ.</div><div v-else class="table-scroll"><table><thead><tr><th>Khách hàng</th><th>Nhóm</th><th>Bill</th><th>Doanh thu</th><th>Mua gần nhất</th></tr></thead><tbody><tr v-for="row in data.rows" :key="row.customerId"><td><strong>{{ row.customerName }}</strong></td><td><span class="segment" :class="row.segment">{{ row.segment === 'new_buyer' ? 'Mới mua' : 'Quay lại' }}</span></td><td>{{ row.invoiceCount }}</td><td>{{ money(row.revenue) }}</td><td>{{ formatDateTime(row.lastPurchaseAt) }}</td></tr></tbody></table></div></template>
  </section>
</template>
<script setup>
import { ref, watch } from 'vue';import axios from 'axios'
const API_BASE=import.meta.env.VITE_API_URL||'http://localhost:5079'
const props=defineProps({fromDate:{type:String,required:true},toDate:{type:String,required:true}});const loading=ref(false);const error=ref('');const data=ref(null);let requestSequence=0
async function load(){const requestId=++requestSequence;loading.value=true;error.value='';try{const response=await axios.get(`${API_BASE}/api/admin/reports/operations/customers`,{params:{fromDate:props.fromDate,toDate:props.toDate},timeout:5000});if(requestId!==requestSequence)return;data.value=response.data?.data||null;if(!data.value)throw new Error('Dữ liệu khách hàng không hợp lệ.')}catch(e){if(requestId===requestSequence)error.value=e.response?.data?.message||e.message||'Chưa tải được khách hàng.'}finally{if(requestId===requestSequence)loading.value=false}}watch(()=>[props.fromDate,props.toDate],load,{immediate:true});function money(value){return `${Number(value||0).toLocaleString('vi-VN',{maximumFractionDigits:0})} ₫`}function formatDateTime(value){return value?new Date(value).toLocaleDateString('vi-VN'):'—'}
</script>
<style scoped>
.operation-block{display:flex;flex-direction:column;gap:12px;padding:16px;background:#fff;border:1px solid #dfe5ef;border-radius:10px;color:#172033}.operation-block header{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.operation-block header button{width:40px;height:40px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#0f766e;font-size:1.1rem;cursor:pointer}.module-eyebrow{margin:0 0 4px;color:#0f766e;font-size:.68rem;font-weight:800;letter-spacing:.1em}.operation-block h3{margin:0;font-size:1rem}.operation-block p:not(.module-eyebrow){margin:4px 0 0;color:#64748b;font-size:.78rem}.mini-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.mini-kpis span{padding:10px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:7px;color:#64748b;font-size:.72rem}.mini-kpis b{display:block;color:#172033;font-size:1rem}.table-scroll{overflow-x:auto;border:1px solid #e2e8f0;border-radius:7px}.operation-block table{width:100%;min-width:600px;border-collapse:collapse;font-size:.75rem}.operation-block th,.operation-block td{padding:8px;border-bottom:1px solid #edf0f5;text-align:left;white-space:nowrap}.operation-block th{background:#f8fafc;color:#64748b;font-size:.67rem;text-transform:uppercase}.operation-block tr:last-child td{border:0}.operation-block small{display:block;color:#94a3b8;margin-top:2px}.block-error{padding:10px;color:#991b1b;background:#fef2f2;border:1px solid #fecaca;border-radius:7px;font-size:.78rem}.block-error button{margin-left:5px;border:0;background:transparent;color:#991b1b;text-decoration:underline;cursor:pointer}.block-loading{min-height:110px;display:grid;place-items:center;color:#64748b;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:7px;font-size:.8rem}.segment{display:inline-flex;padding:3px 6px;border-radius:6px;background:#e0f2fe;color:#075985;font-size:.7rem;font-weight:700}.segment.returning{background:#ecfdf5;color:#047857}@media(max-width:600px){.mini-kpis{grid-template-columns:1fr}.mini-kpis span{display:flex;justify-content:space-between;align-items:center}.mini-kpis b{display:inline}}
</style>
